head.script:
scwin.trigger1_onclick = function(e) {
tabcontrol1.addTab("test1",
							{
								"label": "test1",
								"openAction": "exist",
								"closable": "true"
							},
							{
								"src": "/sample/common_link/mapchart_tabControl_always_WESE-474_(WSQ-5411)_sub1.xml",
								"frameMode" : "wframePreload",
								"scope" : true,
								"alwaysDraw": "true",
								"dataObject":{
									"type" : "json",
									"name" : "tabParam",
									"data" : {
										"a" : "aaaa"
									}
								}
							}
					);
};

scwin.trigger2_onclick = function(e) {
tabcontrol1.addTab("test2",
							{
								"label": "test2",
								"openAction": "exist",
								"closable": "true"
							},
							{
								"src": "/sample/common_link/mapchart_tabControl_always_WESE-474_(WSQ-5411)_sub2.xml",
								"frameMode" : "wframePreload",
								"scope" : true,
								"alwaysDraw": "true",
								"dataObject":{
									"type" : "json",
									"name" : "tabParam",
									"data" : {
										"a" : "aaaa"
									}
								}
							}
					);
};

	scwin.checkVal1 = function() {
		return (document.getElementById('tabcontrol1_contents_test1_body_wq_uuid_11_svg') || document.getElementById('mf_tabcontrol1_contents_test1_body_wq_uuid_11_svg')).getAttribute('width') != '0';
	}
	scwin.checkVal2 = function() {
		return (document.getElementById('tabcontrol1_contents_test1_body_wq_uuid_11_svg') || document.getElementById('mf_tabcontrol1_contents_test1_body_wq_uuid_11_svg')).getAttribute('height') != '0';
	}
	// 지도에 그려진 지역(시도) 개수
	scwin.checkVal3 = function() {
		return (document.getElementById('tabcontrol1_contents_test1_body_wq_uuid_11_svg') || document.getElementById('mf_tabcontrol1_contents_test1_body_wq_uuid_11_svg')).querySelectorAll('path.municipality').length;
	}
